 * allow-list entry avoids a second, separately-maintained list that would drift from the code
 * the moment either one changes.
 *
 * The "nearest blank line" boundary, not a fixed line count, matters: this codebase's real
 * exception comments are often a shared multi-line block covering several sibling declarations
 * (footer.css.ts's four provisional constants share one comment), or wrap the marker word
 * itself across a line break (zimmSubscribeSection.css.ts had "...52/40. Pending\n// Kiera."
 * — "Pending" and "Kiera" on different lines). A fixed N-line window missed both shapes during
 * this script's own first calibration pass against the real codebase.
 *
 * This is a line-based grep, not an AST parse — matches
 * .claude/rules/overrideStyling.md's own framing ("it greps for exactly this"). A real
 * false-positive class this cannot fully rule out: a hex-looking string in a non-colour
 * context (e.g. a URL fragment that happens to be 3-8 hex characters) would still be flagged;
 * mark it with `// audit-allow: <reason>` rather than trying to make the regex smarter.
 *
 * Not wired into CI yet — see overrideStyling.md's note on why (someone needs to own triaging
 * false positives on a real run first).
 */

import { readFileSync, readdirSync, existsSync } from 'fs';
import { join, extname, relative, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const APP = join(ROOT, 'overrides/app');

const SCAN_ROOTS = [join(APP, 'components'), join(APP, 'theme/components')];
const SCAN_EXTENSIONS = new Set(['.ts', '.tsx', '.scss']);

const HEX_RE = /#[0-9a-fA-F]{3,8}\b/g;
const UNIT_RE = /\b\d+(?:\.\d+)?(?:rem|em|px)\b/g;
const EXCEPTION_MARKER_RE = /provisional|pending|placeholder|audit-allow/i;

const isExcludedFile = (filePath) =>
  filePath.endsWith('.test.ts') || filePath.endsWith('.test.tsx') || filePath.endsWith('.stories.tsx');

function walk(dir, files = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, files);
    } else if (SCAN_EXTENSIONS.has(extname(entry.name)) && !isExcludedFile(full)) {
      files.push(full);
    }
  }
  return files;
}

/**
 * Strips `//` and `/* *\/` comment content from a line so a Figma hex value or px measurement
 * mentioned in prose doesn't get flagged as a code violation. Tracks block-comment state across
 * lines via the mutable `state` object the caller owns. `//` is only treated as a comment start
 * when not immediately preceded by `:` — otherwise `'https://wa.me/...'` string literals (real
 * content in this codebase's Contentful fixtures) would truncate the line early.
 */
function stripComments(line, state) {
  let result = '';
  let i = 0;
  while (i < line.length) {
    if (state.inBlockComment) {
      const end = line.indexOf('*/', i);
      if (end === -1) return result;
      i = end + 2;
      state.inBlockComment = false;
      continue;
    }
    if (line[i] === '/' && line[i + 1] === '/' && line[i - 1] !== ':') break;
    if (line[i] === '/' && line[i + 1] === '*') {
      state.inBlockComment = true;
      i += 2;
      continue;
    }
    result += line[i];
    i += 1;
  }
  return result;
}

function scanFile(filePath) {
  const relPath = relative(ROOT, filePath);
  const lines = readFileSync(filePath, 'utf8').split('\n');
  const state = { inBlockComment: false };
  const findings = [];

  lines.forEach((rawLine, idx) => {
    const lineNo = idx + 1;
    const code = stripComments(rawLine, state);

    const matches = [...code.matchAll(HEX_RE), ...code.matchAll(UNIT_RE)];
    if (matches.length === 0) return;

    let contextStart = idx;
    while (contextStart > 0 && lines[contextStart - 1].trim() !== '') contextStart -= 1;
    const context = lines.slice(contextStart, idx + 1).join('\n');
    const acknowledged = EXCEPTION_MARKER_RE.test(context);

    for (const match of matches) {
      findings.push({ file: relPath, line: lineNo, value: match[0], acknowledged, text: rawLine.trim() });
    }
  });

  return findings;
}

const files = SCAN_ROOTS.filter(existsSync).flatMap((root) => walk(root));
const allFindings = files.flatMap(scanFile);
const failures = allFindings.filter((f) => !f.acknowledged);
const acknowledged = allFindings.filter((f) => f.acknowledged);

console.log('Token usage audit');
console.log('==================');
console.log(`Scanned ${files.length} file(s) under overrides/app/components/ and overrides/app/theme/components/\n`);

if (failures.length > 0) {
  console.log(`❌ ${failures.length} raw value(s) with no acknowledged exception:\n`);
  for (const f of failures) {
    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
    console.log(`    ${f.text}`);
  }
  console.log('\n  Reach for a token instead — var(--zimm-color-*) for hex, var(--zimm-scale-*) for px/rem/em.');
  console.log(
    '  If this genuinely has no token yet (pending UI-designer sign-off), name it as a constant\n' +
      '  with a comment containing "provisional"/"pending"/"placeholder", or add "audit-allow: <reason>".',
  );
}

if (acknowledged.length > 0) {
  console.log(`\n✓ ${acknowledged.length} raw value(s) with an acknowledged exception (not failing):`);
  for (const f of acknowledged) {
    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
  }
}

console.log(
  failures.length > 0
    ? `\n${failures.length} unacknowledged violation(s) found.`
    : '\nNo unacknowledged raw hex/px/rem/em literals found.',
);

process.exit(failures.length > 0 ? 1 : 0);

